## Secure Implementation

### Tier 1: Critical Fix (5 minutes)
**Upgrade Spring Framework and Spring Boot immediately**

Spring4Shell requires an OS-level patch to the Spring Framework itself. There is no code workaround—you MUST upgrade.

```xml
<!-- pom.xml -->
<properties>
  <!-- CRITICAL: Must upgrade to patched versions -->
  <!-- Old versions (VULNERABLE): -->
  <!-- 5.3.10, 5.2.19, < 5.0.0 -->

  <!-- Upgrade to MINIMUM patched versions: -->
  <spring-framework.version>5.3.18</spring-framework.version>
  <!-- OR -->
  <spring-framework.version>5.2.20</spring-framework.version>
</properties>

<!-- Alternatively, if using Spring Boot, upgrade Boot version (includes patched Spring): -->
<dependency>
  <groupId>org.springframework.boot</groupId>
  <artifactId>spring-boot-starter-web</artifactId>
  <version>2.6.6</version>  <!-- Minimum patched version -->
  <!-- OR -->
  <version>2.5.12</version>  <!-- For 2.5.x LTS -->
</dependency>
```

**Verify the patch:**
```bash
# Check your current Spring version
mvn dependency:tree | grep spring-framework

# After upgrade, confirm patched version is in use
mvn dependency:tree | grep "spring-framework:5.3.18" || "spring-framework:5.2.20"
```

### Tier 2: Essential Defenses (15 minutes)
**Use @RequestBody annotation for all POJO bindings + Property-based access control**

```java
@RestController
@RequestMapping("/api")
public class UserController {

    // SECURE: Use @RequestBody to bind JSON, not query parameters
    @PostMapping("/profile")
    public ResponseEntity<User> updateProfile(@RequestBody User user) {
        // @RequestBody forces JSON body parsing
        // Direct property binding is disabled
        // class.module.classLoader traversal is blocked
        return ResponseEntity.ok(user);
    }

    // SECURE: If you must use query parameters, use primitive types
    @GetMapping("/users/{id}")
    public ResponseEntity<User> getUserById(
        @PathVariable Long id,  // Direct path variable (safe)
        @RequestParam(required = false) String sortBy  // Primitive type (safe)
    ) {
        // Primitive types can't have property traversal
        return ResponseEntity.ok(userService.findById(id));
    }
}

public class User {
    private Long id;
    private String name;
    private String email;

    // SECURE: Explicitly define which fields can be bound
    // Do NOT expose technical properties like 'class'
    // Getters and setters for safe fields only
}
```

**Configure Spring to restrict property binding (defense-in-depth):**

```java
@Configuration
public class SecurityConfiguration implements WebMvcConfigurer {

    @Override
    public void addFormatters(FormatterRegistry registry) {
        // SECURE: Register custom converter to block dangerous properties
        // This provides defense-in-depth even if other fixes are incomplete
    }
}
```

**OR use WAF rules at the load balancer level:**

```yaml
# AWS ALB Security Group / WAF Rules
# Block any request containing Spring4Shell indicators
rules:
  - Name: "Block-Spring4Shell-ClassLoader"
    Priority: 1
    Statement:
      ByteMatchStatement:
        SearchString: "class.classLoader"
        FieldToMatch:
          QueryString: {}
        TextTransformation: "URL_DECODE"
        PositionalConstraint: "CONTAINS"
    Action: "BLOCK"

  - Name: "Block-Spring4Shell-ModuleClassLoader"
    Priority: 2
    Statement:
      ByteMatchStatement:
        SearchString: "class.module.classLoader"
        FieldToMatch:
          QueryString: {}
        TextTransformation: "URL_DECODE"
        PositionalConstraint: "CONTAINS"
    Action: "BLOCK"

  - Name: "Block-ClassLoader-Pattern"
    Priority: 3
    Statement:
      RegexMatchStatement:
        RegexString: "(?:class|Class)\\.*classLoader"
        FieldToMatch:
          QueryString: {}
        TextTransformation: "URL_DECODE"
    Action: "BLOCK"
```

### Tier 3: Production Hardening (30 minutes)
**Complete defense-in-depth strategy with monitoring**

```java
@Configuration
public class ProductionHardeningConfig {

    /**
     * Tier 3a: Custom servlet filter to detect and block Spring4Shell attempts
     */
    @Bean
    public FilterRegistrationBean<Spring4ShellDetectionFilter> spring4ShellFilter() {
        FilterRegistrationBean<Spring4ShellDetectionFilter> registration = 
            new FilterRegistrationBean<>(new Spring4ShellDetectionFilter());
        registration.addUrlPatterns("/*");
        registration.setOrder(1);  // Execute first, before other filters
        return registration;
    }

    /**
     * Tier 3b: Restrict JDK versions (downgrade to JDK 8 if possible)
     * Spring4Shell only affects JDK 9+
     */
    @Bean
    public JdkVersionValidator jdkValidator() {
        return new JdkVersionValidator();
    }
}

/**
 * Spring4Shell Detection Filter
 * Detects property binding attempts with dangerous class properties
 */
public class Spring4ShellDetectionFilter extends OncePerRequestFilter {

    private static final List<String> DANGEROUS_PATTERNS = Arrays.asList(
        "class.module.classLoader",
        "class.classLoader",
        "Class.module.classLoader",
        "Class.classLoader",
        "classLoader",
        "protectionDomain",
        "accessControlContext"
    );

    private static final MeterRegistry meterRegistry = new SimpleMeterRegistry();
    private static final Counter exploitAttempts = Counter.builder("spring4shell.exploit_attempts")
        .description("Number of Spring4Shell exploit attempts detected")
        .register(meterRegistry);

    @Override
    protected void doFilterInternal(HttpServletRequest request, 
                                   HttpServletResponse response, 
                                   FilterChain filterChain) 
            throws ServletException, IOException {

        // Tier 3c: Decode and inspect query string
        String queryString = request.getQueryString() != null ? 
            URLDecoder.decode(request.getQueryString(), StandardCharsets.UTF_8) : "";

        // Check for dangerous patterns
        for (String pattern : DANGEROUS_PATTERNS) {
            if (queryString.contains(pattern)) {
                // SECURITY: Log attack attempt
                logSecurityEvent("SPRING4SHELL_EXPLOIT_ATTEMPT", 
                    request.getRemoteAddr(), 
                    request.getRequestURI(),
                    pattern);

                exploitAttempts.increment();

                // SECURITY: Block request
                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().write("Access denied");
                return;
            }
        }

        // Check request headers for JSP payload indicators
        Enumeration<String> headerNames = request.getHeaderNames();
        while (headerNames.hasMoreElements()) {
            String headerName = headerNames.nextElement();
            String headerValue = request.getHeader(headerName);

            // Detect JSP code in headers (common in webshell payloads)
            if (containsJavaCode(headerValue)) {
                logSecurityEvent("SPRING4SHELL_JSP_PAYLOAD", 
                    request.getRemoteAddr(),
                    request.getRequestURI(),
                    headerName);

                exploitAttempts.increment();
                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().write("Access denied");
                return;
            }
        }

        filterChain.doFilter(request, response);
    }

    private boolean containsJavaCode(String value) {
        if (value == null) return false;

        // Detect common Java code indicators in headers
        return value.contains("java.lang.Runtime") ||
               value.contains("getRuntime") ||
               value.contains(".exec(") ||
               value.contains("ProcessBuilder") ||
               value.contains("class.module");
    }

    private void logSecurityEvent(String eventType, String sourceIp, 
                                 String uri, String details) {
        // Log to security audit trail
        String message = String.format(
            "SECURITY_EVENT type=%s source_ip=%s uri=%s details=%s timestamp=%s",
            eventType, sourceIp, uri, details, Instant.now()
        );

        System.err.println(message);  // Also to stderr for SIEM pickup
    }
}

/**
 * Tier 3d: Prometheus metrics for monitoring
 */
@Configuration
public class MonitoringConfig {

    @Bean
    public MeterBinder spring4ShellMetrics() {
        return (registry) -> {
            // Track exploit attempts
            Counter.builder("spring4shell.attempts")
                .description("Spring4Shell exploit attempts detected")
                .register(registry);

            // Track Spring version in use (alerting for old versions)
            Gauge.builder("spring.framework.version", 
                () -> getSpringFrameworkVersion())
                .description("Spring Framework version (0=<5.2.20, 1=<5.3.18, 2=patched)")
                .register(registry);
        };
    }

    private int getSpringFrameworkVersion() {
        String version = SpringFramework.VERSION;
        // Return numeric indicator of patch status
        if (version.contains("5.3.18") || version.contains("5.2.20")) return 2;  // Patched
        if (version.startsWith("5.3.")) return 0;  // Unpatched 5.3.x
        if (version.startsWith("5.2.")) return 0;  // Unpatched 5.2.x
        return 1;  // Unknown
    }
}

