## Testing

```java
@SpringBootTest
public class Spring4ShellSecurityTests {

    @Autowired
    private MockMvc mockMvc;

    @Test
    public void testClassLoaderTraversalBlocked() throws Exception {
        // Verify that class.module.classLoader binding is blocked
        mockMvc.perform(get("/api/profile")
            .param("class.module.classLoader.resources.context.parent.pipeline.first.pattern", 
                   "<% Runtime.getRuntime().exec(...) %>"))
            .andExpect(status().isForbidden());
    }

    @Test
    public void testClassLoaderBypassBlocked() throws Exception {
        // Verify bypass attempts also blocked
        mockMvc.perform(get("/api/profile")
            .param("class.classLoader.urls", "http://attacker.com"))
            .andExpect(status().isForbidden());
    }

    @Test
    public void testLegitimateRequestAllowed() throws Exception {
        // Verify legitimate queries still work
        mockMvc.perform(get("/api/profile")
            .param("name", "John")
            .param("email", "john@example.com"))
            .andExpect(status().isOk());
    }

    @Test
    public void testRequestBodyBindingSecure() throws Exception {
        // POST with @RequestBody should always work (safe)
        mockMvc.perform(post("/api/profile")
            .contentType(MediaType.APPLICATION_JSON)
            .content("{\"name\":\"John\",\"email\":\"john@example.com\"}"))
            .andExpect(status().isOk());
    }
}
```

