global:
  scrape_interval: 15s

scrape_configs:
  - job_name: 'spring4shell-monitoring'
    static_configs:
      - targets: ['localhost:8080']
    metrics_path: '/actuator/prometheus'
```

### Alert Rules

```yaml
# alerts.yml
groups:
  - name: spring4shell_alerts
    interval: 30s
    rules:
      - alert: Spring4ShellExploitAttempt
        expr: rate(spring4shell_attempts[5m]) > 0
        for: 1m
        annotations:
          summary: "Spring4Shell exploit attempt detected"
          description: "{{ $value }} attacks detected in last 5 minutes"
          severity: "CRITICAL"

      - alert: UnpatchedSpringFramework
        expr: spring.framework.version == 0
        for: 5m
        annotations:
          summary: "Unpatched Spring Framework running"
          description: "Application running Spring Framework < 5.3.18 or < 5.2.20"
          severity: "CRITICAL"
          action: "Upgrade Spring immediately"
```

